export function buildWeeklyStrategicFocus({sessions=[],candidates=[],recommendations=[],start,end}={}){
  const relevantSessions=sessions.filter(i=>i.date>=start&&i.date<=end);
  const candidatesByTopic=new Map(candidates.filter(i=>i.topicId).map(i=>[i.topicId,i]));
  const totalSeconds=seconds(relevantSessions);
  const highImpactSeconds=seconds(relevantSessions.filter(i=>isHighImpact(candidatesByTopic.get(i.topicId)?.examImpact)));
  const unknownSeconds=seconds(relevantSessions.filter(i=>!i.topicId||candidatesByTopic.get(i.topicId)?.examImpact==null));
  const workedIds=new Set(relevantSessions.filter(i=>{
    const candidate=candidatesByTopic.get(i.topicId);
    return isStrategicGap(candidate);
  }).map(i=>i.topicId));
  const outcomes=new Map();
  for(const i of recommendations){
    if(!workedIds.has(i.topicId)||i.date<start||i.date>end)continue;
    const measuredDate=localDateFromTimestamp(i.outcome?.measuredAt);
    if(!measuredDate||measuredDate<start||measuredDate>end)continue;
    const state=i.outcome?.state;
    if(!['positive','neutral','negative'].includes(state))continue;
    const previous=outcomes.get(i.topicId);
    if(previous!=='positive'&&(state==='positive'||previous!=='negative'))outcomes.set(i.topicId,state);
  }
  const values=[...outcomes.values()];
  return {state:totalSeconds?'available':'insufficient',totalMinutes:Math.round(totalSeconds/60),highImpactMinutes:Math.round(highImpactSeconds/60),unknownMinutes:Math.round(unknownSeconds/60),highImpactPercent:totalSeconds?Math.round(highImpactSeconds/totalSeconds*100):null,workedGaps:workedIds.size,improved:values.filter(value=>value==='positive').length,stable:values.filter(value=>value==='neutral').length,declined:values.filter(value=>value==='negative').length,unmeasured:workedIds.size-outcomes.size};
}
